    # General pattern for clean postcodes
    clean_pattern = re.compile(r'^[0-9A-Za-z-\.\sTJV]{3,10}$')
    if clean_pattern.match(cell):
        return False
    return True

def corrupt(cell):
    error_types = [
        {'func': insert_random_char, 'chance': 0.3},
        {'func': remove_char, 'chance': 0.3},
        {'func': replace_char, 'chance': 0.3},
        {'func': swap_adjacent_chars, 'chance': 0.1},
    ]

    for error in error_types:
        if random.random() < error['chance']:
            return error['func'](cell)

def insert_random_char(cell):
    char_set = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ-."
    index = random.randint(0, len(cell))
    return cell[:index] + random.choice(char_set) + cell[index:]

def remove_char(cell):
    if len(cell) > 1:
        index = random.randint(0, len(cell) - 1)
        return cell[:index] + cell[index+1:]
    return cell

def replace_char(cell):
    char_set = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ-."
    index = random.randint(0, len(cell) - 1)
    return cell[:index] + random.choice(char_set) + cell[index+1:]

def swap_adjacent_chars(cell):
    if len(cell) > 1:
        index = random.randint(0, len(cell) - 2)
        return cell[:index] + cell[index+1] + cell[index] + cell[index+2:]
    return cell

